def transform_gp_structure(individual, X):
    # Modify the primitive set to add arguments for each column
    # Then compile with the correct signature
    pset_modified = gp.PrimitiveSet("MAIN", X.shape[1])
    for name, arity in pset.primitives.items():
        pset_modified.addPrimitive(name, arity)
    for term in pset.terminals:
        pset_modified.addTerminal(*term)

    expr = gp.compile(individual, pset_modified)
    return np.array([expr(*row) for row in X])


